style.css:
@-moz-document domain("netflix.com") {
body {
    background-color: #141414 !important;
}

/* overlay rosa BEM suave */
.mainView::before {
    content: "";
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(255, 182, 193, 0.07); /* bem mais leve */
    pointer-events: none;
    z-index: 0;
}

/* melhorar contraste dos textos */
h1, h2, h3, span, p {
    color: #ffffff !important;
}

/* botões rosinha sem quebrar */
button {
    border-radius: 20px !important;
}

button:hover {
    box-shadow: 0 0 8px rgba(255, 182, 193, 0.4) !important;
}
}
